contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address other, uint depositAmount, uint collectAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (depositAmount) + (collectAmount)); require(depositAmount <= 1000000000000000000000000000000); require(collectAmount <= 1000000000000000000000000000000);
        require(other != address(this), "other must differ from caller");
        require(other != address(c), "other must differ from c");
        require(address(this).balance >= depositAmount + collectAmount, "insufficient balance");
        require(collectAmount > 0, "collect amount must be positive");

        c.SetMinSum(0); if (__ESBMC_reverted()) return;

        c.Deposit{value: depositAmount}(); if (__ESBMC_reverted()) return;

        c.Deposit{value: collectAmount}(); if (__ESBMC_reverted()) return;

        uint callerBefore = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint otherBefore = c.balances(other); if (__ESBMC_reverted()) return;

        bool reverted;
        c.Collect(collectAmount); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint callerAfter = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint otherAfter = c.balances(other); if (__ESBMC_reverted()) return;
        assert(!reverted && callerAfter == callerBefore - collectAmount && otherAfter == otherBefore);
    }

    receive() external payable {}
}

